delete from data_fill_form_template
where id in

    #{id}

mapper.select:
select count(*)
from data_fill_form_template
where name = #{name}
and pid = #{pid}
and node_type = #{nodeType}

    and id != #{id}

select data_fill_form_template.*, su.nick_name as creatorName, authInfo.privileges as `privileges` from (select GET_V_AUTH_MODEL_ID_P_USE(#{userId}, 'data_fill_template') cids) t, data_fill_form_template left join (SELECT auth_source, group_concat(DISTINCT sys_auth_detail.privilege_extend) as `privileges` FROM ( `sys_auth` LEFT JOIN `sys_auth_detail` ON (( `sys_auth`.`id` = `sys_auth_detail`.`auth_id` ))) WHERE sys_auth_detail.privilege_value = 1 AND sys_auth.auth_source_type = 'data_fill_template' AND ( ( sys_auth.auth_target_type = 'dept' AND sys_auth.auth_target IN (SELECT dept_id FROM sys_user WHERE user_id = #{userId}) ) OR ( sys_auth.auth_target_type = 'user' AND sys_auth.auth_target = #{userId} ) OR ( sys_auth.auth_target_type = 'role' AND sys_auth.auth_target IN (SELECT role_id FROM sys_users_roles WHERE user_id = #{userId}) ) ) GROUP BY `sys_auth`.`auth_source`) authInfo on data_fill_form_template.id = authInfo.auth_source left join sys_user su on su.username = data_fill_form_template.create_by WHERE FIND_IN_SET(data_fill_form_template.id, cids)
and data_fill_form_template.pid = #{pid} and data_fill_form_template.node_type != 'folder'
AND data_fill_form_template.id = #{id}
AND data_fill_form_template.name LIKE CONCAT('%', #{name}, '%')
AND data_fill_form_template.node_type = #{nodeType}
AND data_fill_form_template.status = #{status}
order by data_fill_form_template.create_time desc

select data_fill_form_template.*, data_fill_form_template.`name` as label, authInfo.privileges as `privileges`, su.nick_name as creatorName from (select GET_V_AUTH_MODEL_ID_P_USE (#{userId}, 'data_fill_template') cids) t, data_fill_form_template left join ( SELECT auth_source, group_concat( DISTINCT sys_auth_detail.privilege_extend ) as `privileges` FROM ( `sys_auth` LEFT JOIN `sys_auth_detail` ON (( `sys_auth`.`id` = `sys_auth_detail`.`auth_id` ))) WHERE sys_auth_detail.privilege_value = 1 AND sys_auth.auth_source_type = 'data_fill_template' AND ( ( sys_auth.auth_target_type = 'dept' AND sys_auth.auth_target IN ( SELECT dept_id FROM sys_user WHERE user_id = #{userId} ) ) OR ( sys_auth.auth_target_type = 'user' AND sys_auth.auth_target = #{userId} ) OR ( sys_auth.auth_target_type = 'role' AND sys_auth.auth_target IN ( SELECT role_id FROM sys_users_roles WHERE user_id = #{userId} ) ) ) GROUP BY `sys_auth`.`auth_source` ) authInfo on data_fill_form_template.id = authInfo.auth_source left join sys_user su on su.user_id = data_fill_form_template.create_by
FIND_IN_SET(data_fill_form_template.id, cids)
and data_fill_form_template.id = #{id,jdbcType=VARCHAR}
and data_fill_form_template.pid = #{pid,jdbcType=VARCHAR}
and data_fill_form_template.node_type = #{nodeType,jdbcType=VARCHAR}
and data_fill_form_template.`level` = #{level,jdbcType=INTEGER}
and data_fill_form_template.create_by = #{createBy,jdbcType=VARCHAR},
and data_fill_form_template.create_time = #{createTime,jdbcType=TIMESTAMP},
and data_fill_form_template.update_by = #{updateBy,jdbcType=VARCHAR},
and data_fill_form_template.update_time = #{updateTime,jdbcType=TIMESTAMP},
and data_fill_form_template.id != #{excludedId,jdbcType=VARCHAR}
and data_fill_form_template.id in
#{item}
ORDER BY CONVERT(`name` using gbk)
